		/// <summary>Delivers an event frame to its handlers; false when nothing handled it.</summary>
		public bool Dispatch(ServerFrame frame)
		{
			if (frame is null) throw new ArgumentNullException(nameof(frame));
			if (frame.IsReply) return false;
			if (!handlers.TryGetValue(frame.Type, out var list) || list.Count == 0) return false;
			foreach (var handler in list.ToArray()) handler(frame);
			return true;
		}
	}
